import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Sidebar from '../components/Sidebar';
import '../css/Management.css';
import { API_BASE_URL } from '../constants/api';

const formatSingaporeDateTime = (value) => new Intl.DateTimeFormat('en-SG', {
  timeZone: 'Asia/Singapore',
  dateStyle: 'medium',
  timeStyle: 'short'
}).format(new Date(value));

const getInviteStatus = (invite) => invite.status || (invite.isUsed ? 'USED' : 'PENDING');
const statusClass = (status) => status.toLowerCase();

const formatRemaining = (expiresAt, now = Date.now()) => {
  const diffMs = new Date(expiresAt).getTime() - now;
  if (!Number.isFinite(diffMs) || diffMs <= 0) return 'Expired';
  const totalMinutes = Math.ceil(diffMs / 60000);
  const days = Math.floor(totalMinutes / 1440);
  const hours = Math.floor((totalMinutes % 1440) / 60);
  const minutes = totalMinutes % 60;
  const parts = [];
  if (days) parts.push(`${days} day${days === 1 ? '' : 's'}`);
  if (hours) parts.push(`${hours} hour${hours === 1 ? '' : 's'}`);
  if (!days && minutes) parts.push(`${minutes} min${minutes === 1 ? '' : 's'}`);
  return `Valid for ${parts.join(' ') || 'less than 1 min'}`;
};

const getDisplayStatus = (invite, now = Date.now()) => {
  const status = getInviteStatus(invite);
  if (status === 'PENDING' && new Date(invite.expiresAt).getTime() <= now) return 'EXPIRED';
  return status;
};

const TenantManagement = () => {
  const [invites, setInvites] = useState([]);
  const [newCode, setNewCode] = useState(null);
  const [loading, setLoading] = useState(false);
  const [now, setNow] = useState(() => Date.now());

  const token = localStorage.getItem('accessToken');
  const userName = localStorage.getItem('userName');

  const fetchInvites = async () => {
    try {
      const res = await axios.get(`${API_BASE_URL}/user/tenant-invites`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setInvites(res.data);
    } catch (err) {
      console.error('Failed to fetch invites');
    }
  };

  useEffect(() => {
    fetchInvites();
  }, []);

  useEffect(() => {
    const timer = setInterval(() => {
      const nextNow = Date.now();
      setNow(nextNow);
      if (invites.some((invite) => getInviteStatus(invite) === 'PENDING' && new Date(invite.expiresAt).getTime() <= nextNow)) {
        fetchInvites();
      }
    }, 60000);
    return () => clearInterval(timer);
  }, [invites]);

  const handleGenerateInvite = async () => {
    setLoading(true);
    try {
      const res = await axios.post(`${API_BASE_URL}/user/invite-tenant`, {}, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setNewCode(res.data.inviteCode);
      fetchInvites();
    } catch (err) {
      alert('Error generating invitation');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="dashboard-layout">
      <Sidebar />
      <main className="dashboard-main">
        <header className="dashboard-header">
          <div className="header-titles">
            <h1>Tenant Onboarding</h1>
            <p>Unit Controller: <strong>{userName}</strong></p>
          </div>
        </header>

        <div className="management-container">
          <div className="code-generator-card">
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '10px' }}>
              <h3 style={{ margin: 0 }}>Issue New Invitation</h3>
              <p style={{ margin: 0, color: '#64748b', fontSize: '0.8rem', fontWeight: '500' }}>
                Generate secure invitation codes for new Unit Owners.
              </p>
            </div>

            <p style={{ color: '#94a3b8', fontSize: '0.85rem', marginBottom: '25px' }}>
              Each code is one-time use and expires in 48 hours. New unit owners can self-register
              securely with this invite code — an alternative to adding them from User Management.
            </p>

            <div className="code-flex-row">
              <div className="code-display-box" style={{ minWidth: '250px' }}>
                {newCode || '---- ---- ----'}
              </div>
              <button
                onClick={handleGenerateInvite}
                className="edit-btn"
                disabled={loading}
                style={{ background: '#3b82f6', color: 'white', padding: '14px 24px' }}
              >
                {loading ? 'Generating...' : 'Generate Invite Code'}
              </button>
            </div>

            {newCode && (
              <p style={{ marginTop: '15px', color: '#10b981', fontSize: '0.85rem', fontWeight: '600' }}>
                Copy this code and send it to the new Tenant.
              </p>
            )}
          </div>

          <div className="table-container">
            <table className="management-table">
              <thead>
                <tr>
                  <th>INVITATION CODE</th>
                  <th>EXPIRATION</th>
                  <th>STATUS</th>
                  <th>CREATED ON</th>
                </tr>
              </thead>
              <tbody>
                {invites.length > 0 ? invites.map((invite) => {
                  const status = getDisplayStatus(invite, now);
                  return (
                    <tr key={invite.id}>
                      <td style={{ fontFamily: 'monospace', fontWeight: 'bold', letterSpacing: '1px' }}>{invite.code}</td>
                      <td data-label="Expiration">{formatSingaporeDateTime(invite.expiresAt)}</td>
                      <td data-label="Status">
                        <span className={`status-badge ${statusClass(status)}`} role="status" aria-label={`Invitation status: ${status}`}>
                          {status}
                        </span>
                        {status === 'PENDING' && invite.isUsable && (
                          <span className="invite-expiry-block" aria-label={`Invitation expires ${formatSingaporeDateTime(invite.expiresAt)}`}>
                            <span className="invite-expiry-icon" aria-hidden="true">◷</span>
                            <span>
                              <strong>{formatRemaining(invite.expiresAt, now)}</strong>
                              <small>Expires {formatSingaporeDateTime(invite.expiresAt)}</small>
                            </span>
                          </span>
                        )}
                        {status === 'USED' && <span className="invite-final-note">Used</span>}
                        {status === 'EXPIRED' && <span className="invite-final-note">Expired {formatSingaporeDateTime(invite.expiresAt)}</span>}
                      </td>
                      <td data-label="Created">{formatSingaporeDateTime(invite.createdAt)}</td>
                    </tr>
                  );
                }) : (
                  <tr>
                    <td colSpan="4" style={{ textAlign: 'center', padding: '40px', color: '#64748b' }}>
                      No active invitations found.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      </main>
    </div>
  );
};

export default TenantManagement;
