import VisibilityIcon from '@mui/icons-material/Visibility';
import BlockIcon from '@mui/icons-material/Block';
import CheckCircleIcon from '@mui/icons-material/CheckCircle';
import PersonOffIcon from '@mui/icons-material/PersonOff';

const formatPct = (value) => (value == null ? null : `${Math.round(Number(value) * 100)}%`);
const formatLatency = (value) => (value == null ? null : `${Math.round(Number(value))} ms`);

const stateIcon = {
  granted: CheckCircleIcon,
  denied: BlockIcon,
  noface: PersonOffIcon,
  neutral: VisibilityIcon
};

const deriveVariant = (decision) => decision.variant
  || (decision.accountState === 'No Face' ? 'noface' : decision.accessLabel === 'Access Granted' ? 'granted' : decision.accessLabel === 'Access Denied' ? 'denied' : 'neutral');

const deriveDetails = (decision, variant) => {
  if (decision.details) return decision.details;
  if (variant === 'noface') {
    return [
      { label: 'Monitoring status', value: 'Awaiting a person' },
      { label: 'Access decision', value: 'None required' },
      { label: 'System action', value: 'No attendance or suspicious security log created' }
    ];
  }
  return [
    ...(decision.accountState ? [{ label: 'Account', value: decision.accountState }] : []),
    ...(decision.liveness ? [{ label: 'Liveness', value: decision.liveness }] : []),
    ...(decision.action ? [{ label: 'System action', value: decision.action }] : [])
  ];
};

const RecognitionDecisionCard = ({ decision, onRecordEvaluation, matrixHref = '/facial-evaluation?tab=matrix&source=Live' }) => {
  if (!decision) return null;
  const variant = deriveVariant(decision);
  const Icon = stateIcon[variant] || VisibilityIcon;
  const result = decision.result || decision.evaluationResult;
  const confidence = formatPct(decision.confidence ?? result?.confidence ?? result?.user?.confidence);
  const latency = formatLatency(decision.latencyMs ?? result?.timings?.totalRequestMs ?? result?.timings?.nodeToAiMs);
  const recordLabel = variant === 'noface' ? 'Record No-Face Test' : 'Record for Evaluation';
  const headline = decision.headline || (variant === 'noface' ? 'No face detected' : `${decision.identityLabel || 'Unknown Person'} — ${decision.accessLabel || 'Access Decision'}`);
  const details = deriveDetails(decision, variant);

  return (
    <section className={`recognition-decision-card ${variant}`} aria-label="Recognition decision">
      <div className="recognition-decision-head">
        <Icon aria-hidden="true" fontSize="small" />
        <div>
          <h3>{headline}</h3>
          {decision.timestamp && <small>{new Intl.DateTimeFormat('en-SG', { timeZone: 'Asia/Singapore', dateStyle: 'medium', timeStyle: 'medium' }).format(new Date(decision.timestamp))}</small>}
        </div>
      </div>
      <dl className="recognition-decision-details">
        {details.map((item) => <div key={item.label}><dt>{item.label}</dt><dd>{item.value}</dd></div>)}
        {confidence && <div><dt>Confidence</dt><dd>{confidence}</dd></div>}
        {latency && <div><dt>Latency</dt><dd>{latency}</dd></div>}
        {decision.cameraSource && <div><dt>Source camera</dt><dd>{decision.cameraSource}</dd></div>}
      </dl>
      <div className="recognition-decision-actions">
        {result && <button type="button" onClick={() => onRecordEvaluation?.(result)}>{recordLabel}</button>}
        {decision.message && <span>{decision.message}</span>}
        {decision.message && <a href={matrixHref}>View Live Confusion Matrix</a>}
      </div>
    </section>
  );
};

export default RecognitionDecisionCard;
